import("stdfaust.lib");

// Gate and note controls
gate = button("Gate");
freq = hslider("Frequency [unit:Hz]", 440, 20, 8000, 0.1);

// Envelope controls
attack = hslider("Attack [unit:ms]", 5, 1, 500, 1) / 1000.0;
decay = hslider("Decay [unit:ms]", 200, 1, 2000, 1) / 1000.0;
sustain = hslider("Sustain", 0.6, 0, 1, 0.01);
release = hslider("Release [unit:ms]", 1200, 50, 5000, 1) / 1000.0;

// Filter envelope controls
filterAttack = hslider("Filter Attack [unit:ms]", 80, 1, 1000, 1) / 1000.0;
filterDecay = hslider("Filter Decay [unit:ms]", 400, 1, 3000, 1) / 1000.0;
filterSustain = hslider("Filter Sustain", 0.3, 0, 1, 0.01);
filterRelease = hslider("Filter Release [unit:ms]", 2000, 50, 8000, 1) / 1000.0;

// Filter range
filterFloor = hslider("Filter Floor [unit:Hz]", 200, 20, 2000, 1);
filterCeil = hslider("Filter Ceiling [unit:Hz]", 12000, 1000, 20000, 1);
filterQ = hslider("Filter Q", 3.0, 0.5, 12, 0.1);

// Brightness / harmonics
brightness = hslider("Brightness", 0.7, 0, 1, 0.01);

// Amp envelope (ADSR)
ampEnv = en.adsr(attack, decay, sustain, release, gate);

// Filter envelope (ADSR) - blooms open on press, sighs on release
filtEnv = en.adsr(filterAttack, filterDecay, filterSustain, filterRelease, gate);

// Cutoff frequency driven by filter envelope
cutoff = filterFloor + (filterCeil - filterFloor) * filtEnv;

// Oscillator: mix of sawtooth and pulse for bright sharp character
saw = os.sawtooth(freq);
saw2 = os.sawtooth(freq * 1.001);
pulse = os.pulsetrain(freq, 0.3);
osc = saw * 0.4 + saw2 * 0.25 + pulse * 0.35 * brightness;

// Sub oscillator for body
sub = os.osc(freq * 0.5) * 0.15;

// Combined source
source = osc + sub;

// Filter and shape
filtered = source : fi.resonlp(cutoff, filterQ, 1.0);

// Final output with amp envelope
voice = filtered * ampEnv * 0.5;

// Stereo with slight detune shimmer
saw_r = os.sawtooth(freq * 1.003);
saw2_r = os.sawtooth(freq * 0.998);
pulse_r = os.pulsetrain(freq * 1.001, 0.3);
osc_r = saw_r * 0.4 + saw2_r * 0.25 + pulse_r * 0.35 * brightness;
source_r = osc_r + sub;
filtered_r = source_r : fi.resonlp(cutoff, filterQ, 1.0);
voice_r = filtered_r * ampEnv * 0.5;

process = voice, voice_r;

