// "Popcorn" lead - raw buzzing analog synth sound
// Classic Moog-style square/saw hybrid with tight filter

freq = hslider("Frequency [unit:Hz]", 440, 50, 5000, 0.1);
detune = hslider("Detune [unit:cents]", 5, 0, 50, 0.1);
cutoff = hslider("Filter Cutoff [unit:Hz]", 2500, 100, 15000, 1);
