envAmount = hslider("Env Amount", 4000, 0, 10000, 1);
envDecay = hslider("Env Decay [unit:ms]", 80, 10, 500, 1);
gain = hslider("Gain [unit:dB]", -6, -60, 6, 0.1) : ba.db2linear;
gate = button("Gate");

// Detuned frequency
freq2 = freq * ba.cent2ratio(detune);
freq3 = freq * ba.cent2ratio(0 - detune);

// Oscillators - mix of sawtooth waves for that raw buzzing character
osc1 = os.sawtooth(freq);
osc2 = os.sawtooth(freq2) * 0.7;
osc3 = os.sawtooth(freq3) * 0.7;

// Sub oscillator one octave down (square-ish)
sub = os.square(freq * 0.5) * 0.3;

// Mix oscillators
oscMix = (osc1 + osc2 + osc3 + sub) * 0.4;

// Simple decay envelope for filter
envDecaySamples = envDecay * 0.001 * ma.SR;
env = gate : ba.impulsify : fi.resonlp(1.0 / (envDecay * 0.001), 0.707, 1.0) with {
    // Use a simple one-pole decay
};

// Simpler approach: gate into a leaky integrator for snappy decay
filterEnv = gate * envAmount : si.smooth(ba.tau2pole(envDecay * 0.001));

// Filter with envelope modulation
filterFreq = min(cutoff + filterEnv, 18000);

// Resonant low-pass filter - the Moog-style buzzy character
filtered = oscMix : fi.resonlp(filterFreq, resonance, 1.0) : fi.resonlp(filterFreq, resonance * 0.5, 1.0);

// Simple amplitude envelope - snappy attack, short decay
ampEnv = gate : si.smooth(ba.tau2pole(0.002)) : si.smooth(ba.tau2pole(0.15));

// Output with slight saturation for analog grit
saturate(x) = ma.tanh(x * 1.5) * 0.7;

process = filtered * ampEnv * gain : saturate <: _, _;

