import("stdfaust.lib");

// Bell/glass tone generator - combines inharmonic partials with chorus for glassy robot choir effect

// Controls
freq = hslider("Frequency [unit:Hz]", 440, 100, 2000, 0.1);
brightness = hslider("Brightness", 0.7, 0, 1, 0.01);
shimmer = hslider("Shimmer", 0.5, 0, 1, 0.01);
decay = hslider("Decay [unit:s]", 2.0, 0.1, 8.0, 0.01);
chorusDepth = hslider("Chorus Depth", 0.3, 0, 1, 0.01);
chorusRate = hslider("Chorus Rate [unit:Hz]", 1.5, 0.1, 6.0, 0.01);
volume = hslider("Volume [unit:dB]", -12, -60, 0, 0.1) : ba.db2linear;
gate = button("Gate");

// Envelope - exponential decay triggered by gate
env = gate : en.ar(0.001, decay);

// Inharmonic bell partials (ratios typical of bells/glass)
partial(ratio, amp, detune) = os.osc(freq * ratio + detune) * amp;

// Main bell tone with inharmonic partials
bellTone = partial(1.0, 1.0, 0)
         + partial(2.76, 0.6 * brightness, 0.5)
         + partial(4.07, 0.4 * brightness, -0.3)
         + partial(5.41, 0.3 * brightness * brightness, 0.7)
         + partial(6.72, 0.15 * brightness * brightness, -0.4)
         + partial(8.21, 0.1 * brightness * brightness * brightness, 0.2);

// Glass-like high harmonics for shimmer
glassTone = os.osc(freq * 3.0 + os.osc(5.3) * 2.0) * 0.15 * shimmer
          + os.osc(freq * 5.5 + os.osc(3.7) * 1.5) * 0.1 * shimmer
          + os.osc(freq * 7.2 + os.osc(7.1) * 1.0) * 0.05 * shimmer;

// Robot choir: slightly detuned copies with vibrato
choirVoice(detHz, vibRate, vibDepth) = os.osc(freq + detHz + os.osc(vibRate) * vibDepth);
robotChoir = choirVoice(0.5, 4.8, 1.2) * 0.3
           + choirVoice(-0.7, 5.3, 1.5) * 0.3
           + choirVoice(1.2, 4.1, 0.8) * 0.25
           + choirVoice(-1.5, 5.8, 1.0) * 0.25;

// Combine sources
combined = (bellTone + glassTone + robotChoir * 0.4) * env * volume / 3.0;

// Stereo chorus effect using modulated delays
maxDel = 4096;
chorusLfo1 = os.osc(chorusRate) * 0.5 + 0.5;
chorusLfo2 = os.osc(chorusRate * 1.13 + 0.3) * 0.5 + 0.5;
delSamples1 = int(chorusLfo1 * chorusDepth * 200 + 100);
delSamples2 = int(chorusLfo2 * chorusDepth * 220 + 110);

chorusL(x) = x * 0.6 + de.delay(maxDel, delSamples1, x) * 0.4;
chorusR(x) = x * 0.6 + de.

import("stdfaust.lib");

// DX7 Electric Piano - Classic 80s FM Synthesis
// Inspired by the iconic E.Piano 1 patch

gate = button("Gate");
freq = hslider("Freq [unit:Hz]", 440, 50, 2000, 0.1);
vel = hslider("Velocity", 0.8, 0, 1, 0.01);
brightness = hslider("Brightness", 0.7, 0, 1, 0.01);
detune = hslider("Detune [unit:cents]", 1.5, 0, 10, 0.1);

// Envelope generator: attempt classic DX7 snappy attack, medium decay, gentle sustain
env_attack = 0.001;
env_decay1 = 0.08;
env_decay2 = 2.0;
env_sustain = 0.3;
env_release = 0.4;

// Main amplitude envelope
amp_env = en.adsr(env_attack, env_decay1 + env_decay2 * 0.5, env_sustain, env_release, gate);

// Modulator envelope (brighter on attack, decays quickly)
mod_env = en.adsr(0.001, 0.15, 0.1 * brightness, 0.3, gate);

// FM synthesis: 2-operator pairs mimicking DX7 algorithm 5
// Operator ratios typical of DX7 E.Piano: carriers at 1x, modulators at ~1x, 7x, 14x

// Modulation indices
mod_index1 = 5.0 * brightness * mod_env * vel;
mod_index2 = 2.5 * brightness * mod_env * vel;
mod_index3 = 1.0 * brightness * mod_env * vel;

// Slight detune for richness
detune_hz = freq * detune / 1200.0;

// Operator stack 1: harmonic content (ratio 1:1 with high harmonics)
op_mod3 = os.osc(freq * 14.0) * mod_index3 * freq;
op_mod2 = os.osc(freq * 7.0 + op_mod3) * mod_index2 * freq;
op_carrier1 = os.osc(freq + op_mod2) * amp_env;

// Operator stack 2: slightly detuned for chorus-like warmth
op_mod3b = os.osc((freq + detune_hz) * 14.0) * mod_index3 * freq;
op_mod2b = os.osc((freq + detune_hz) * 1.0 + op_mod3b) * mod_index1 * freq;
op_carrier2 = os.osc(freq + detune_hz + op_mod2b) * amp_env;

// Velocity-sensitive "tine" attack layer (high frequency ping)
tine_env = en.adsr(0.0005, 0.04, 0.0, 0.05, gate);
tine = os.osc(freq * 7.0) * tine_env * vel * 0.15 * brightness;

// Mix carriers
raw = (op_carrier1 * 0.5 + op_carrier2 * 0.4 + tine) * vel * 0.4;

// Gentle low-pass to tame harsh highs
filtered = raw : fi.resonlp(4000 + brightness * 8000, 0.707, 1.0);

// Stereo spread with slight delay
spread_time = 0.003;
spread_samples = int(spread_time * ma.SR);

left = filtered;
right = filtered : de.delay(4096, spread_samples);

process = left, right;

