import("stdfaust.lib");

// Ocean spray / distant waterfall synthesizer
// White noise shaped by filtering and gentle modulation

brightness = hslider("Brightness [unit:Hz]", 2000, 200, 16000, 1);
darkness = hslider("Darkness (LP Q)", 0.5, 0.1, 2.0, 0.01);
rumble = hslider("Rumble [unit:Hz]", 150, 30, 500, 1);
volume = hslider("Volume [unit:dB]", -12, -60, 0, 0.1) : ba.db2linear;
movement = hslider("Movement Rate [unit:Hz]", 0.15, 0.01, 1.0, 0.01);
depth = hslider("Movement Depth", 0.3, 0, 0.8, 0.01);

// Slow LFO for natural modulation
lfo1 = os.osc(movement) * depth;
lfo2 = os.osc(movement * 0.73 + 0.01) * depth;

// Modulated cutoff frequencies
cutoffL = brightness * (1 + lfo1) : max(20) : min(20000);
cutoffR = brightness * (1 + lfo2) : max(20) : min(20000);

// Two independent noise sources for stereo width
noiseL = no.noise;
noiseR = no.noise; // different instance = decorrelated

// Shape the noise: highpass to remove DC/sub rumble, then lowpass for brightness control
shapeL = noiseL : fi.resonhp(rumble, 0.707, 1.0) : fi.resonlp(cutoffL, darkness, 1.0) : fi.resonlp(cutoffL * 1.2, 0.5, 1.0);
shapeR = noiseR : fi.resonhp(rumble, 0.707, 1.0) : fi.resonlp(cutoffR, darkness, 1.0) : fi.resonlp(cutoffR * 1.2, 0.5, 1.0);

// Add a subtle surge/swell layer (very slow amplitude modulation)
surgeL = 1.0 + os.osc(0.08) * 0.15 + os.osc(0.13) * 0.1;
surgeR = 1.0 + os.osc(0.09) * 0.15 + os.osc(0.11) * 0.1;

process = shapeL * surgeL * volume, shapeR * surgeR * volume;

import("stdfaust.lib");

// Wind/surf sleep machine built from filtered white noise

// Controls
wind_speed = hslider("Wind Speed", 0.5, 0, 1, 0.01);
surf_rate = hslider("Surf Rate [unit:Hz]", 0.08, 0.02, 0.5, 0.001);
surf_depth = hslider("Surf Depth", 0.7, 0, 1, 0.01);
brightness = hslider("Brightness [unit:Hz]", 2000, 200, 8000, 1);
volume = hslider("Volume [unit:dB]", -12, -60, 0, 0.1) : ba.db2linear;

// LFO for surf modulation - multiple slow oscillators for organic feel
lfo1 = os.osc(surf_rate) * 0.5 + 0.5;
lfo2 = os.osc(surf_rate * 0.7 + 0.01) * 0.3 + 0.5;
lfo3 = os.osc(surf_rate * 1.3 + 0.02) * 0.2 + 0.5;
surf_mod = (lfo1 * 0.5 + lfo2 * 0.3 + lfo3 * 0.2) * surf_depth + (1 - surf_depth);

// Slightly different modulation for right channel
lfo1r = os.osc(surf_rate * 1.02) * 0.5 + 0.5;
lfo2r = os.osc(surf_rate * 0.68 + 0.015) * 0.3 + 0.5;
lfo3r = os.osc(surf_rate * 1.28 + 0.025) * 0.2 + 0.5;
surf_mod_r = (lfo1r * 0.5 + lfo2r * 0.3 + lfo3r * 0.2) * surf_depth + (1 - surf_depth);

// Cutoff frequency modulated by surf and wind speed
cutoff_base = brightness * (0.3 + 0.7 * wind_speed);
cutoff_l = cutoff_base * surf_mod : max(20) : min(18000);
cutoff_r = cutoff_base * surf_mod_r : max(20) : min(18000);

// Two independent noise sources for stereo width
noise_l = no.noise;
noise_r = no.multinoise(2) : _, !;

// Apply filtering: low-pass for warmth, then gentle high-pass to remove rumble
filtered_l = noise_l : fi.resonlp(cutoff_l, 0.7, 1.0) : fi.resonlp(cutoff_l * 0.8, 0.5, 1.0) : fi.resonhp(40, 0.7, 1.0);
filtered_r = noise_r : fi.resonlp(cutoff_r, 0.7, 1.0) : fi.resonlp(cutoff_r * 0.8, 0.5, 1.0) : fi.resonhp(40, 0.7, 1.0);

// Apply volume envelope from surf modulation and master volume
out_l = filtered_l * surf_mod * volume;
out_r = filtered_r * surf_mod_r * volume;

process = out_l, out_r;
